/*
 * The original Panzer Dragoon (pd1.xbe, from Pandora's Box): its manual
 * lookup and build identity.
 *
 * Everything under src/pd1/ is pd1's: tools/recomp.py --program pd1 scans
 * only this folder for overrides (void sub_XXXXXXXX(void), _enter hooks),
 * with pd1's own addresses, and CMake compiles it with gen-pd1/pd1_names.h
 * force-included, so sub_XXXXXXXX here links as pd1_sub_XXXXXXXX and
 * recomp_lookup as pd1_recomp_lookup. Orta's sources never see these.
 */

#include "recomp_types.h"
#include "pd1_build_info.h"     /* generated by tools/recomp.py --program pd1 */

/* Indirect-call targets the dispatch table does not have. None yet. */
recomp_func_t recomp_lookup_manual(uint32_t xbox_va)
{
    (void)xbox_va;
    return NULL;
}

const char *pd1_built_from(void)
{
    return PD1_BUILD_IMAGE_SHA256;
}
